    property!{
        hash_is_right(key: Key, row: Row, col: Col) {
            require row < HEIGHT;
            require col < WIDTH;
            have matrix >= [row => let r];
            require let Some((entry_key, entry_value)) = r[col as int];
            require entry_key == key;
            assert row == hash1(key) || row == hash2(key);
