        delete_key_value(key: Key, row: Row, col: Col) {
            remove frag -= [key => let _];
            require row < HEIGHT;
            require col < WIDTH;
            remove matrix -= [row => let r];
            require let Some((entry_key, entry_value)) = r[col as int];
            require entry_key == key;
            add matrix += [row => r.update(col as int, None)];
            add frag += [key => None];
